WITH oracle_1 AS (SELECT mktcode,tgtcode,bizdate FROM `newzl`.`hsj_stock_hq_basic_technical` WHERE bizdate='2026-04-14' AND ABS(ma5-ma20)/NULLIF(GREATEST(ABS(ma5),ABS(ma20)),0)<=0.03), branch_1 AS (SELECT o.mktcode,o.tgtcode,o.bizdate FROM oracle_1 o INNER JOIN newzl.hsj_stock_hq_basic q ON q.mktcode=o.mktcode AND q.tgtcode=o.tgtcode AND q.bizdate=o.bizdate WHERE q.mktcode=0 AND q.volume>=100), oracle_2 AS (WITH w AS (SELECT mktcode,tgtcode,bizdate,highPx/10000.0 AS px,MAX(highPx/10000.0) OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate ROWS BETWEEN 59 PRECEDING AND CURRENT ROW) AS extreme FROM `newzl`.`hsj_stock_hq_basic`) SELECT mktcode,tgtcode,bizdate FROM w WHERE bizdate='2026-04-14' AND px>=extreme), branch_2 AS (SELECT o.mktcode,o.tgtcode,o.bizdate FROM oracle_2 o INNER JOIN newzl.hsj_stock_hq_basic q ON q.mktcode=o.mktcode AND q.tgtcode=o.tgtcode AND q.bizdate=o.bizdate WHERE 1=1 AND q.volume>=1), oracle_3 AS (WITH w AS (SELECT mktcode,tgtcode,bizdate,lastPx/10000.0 AS px,MIN(lastPx/10000.0) OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate ROWS BETWEEN 9 PRECEDING AND CURRENT ROW) AS lo,MAX(lastPx/10000.0) OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate ROWS BETWEEN 9 PRECEDING AND CURRENT ROW) AS hi FROM `newzl`.`hsj_stock_hq_basic`) SELECT mktcode,tgtcode,bizdate FROM w WHERE bizdate='2026-04-14' AND CASE WHEN px IS NULL OR lo IS NULL OR hi IS NULL THEN NULL WHEN px<=lo THEN '最低' WHEN px>=hi THEN '最高' WHEN (px-lo)/NULLIF(hi-lo,0)<=0.25 THEN '低' WHEN (px-lo)/NULLIF(hi-lo,0)>=0.75 THEN '高' ELSE '中' END='最高'), branch_3 AS (SELECT o.mktcode,o.tgtcode,o.bizdate FROM oracle_3 o INNER JOIN newzl.hsj_stock_hq_basic q ON q.mktcode=o.mktcode AND q.tgtcode=o.tgtcode AND q.bizdate=o.bizdate WHERE q.mktcode=0 AND q.volume>=1000), nested_pair AS (SELECT mktcode,tgtcode,bizdate FROM branch_1 UNION DISTINCT SELECT mktcode,tgtcode,bizdate FROM branch_2) SELECT l.mktcode,l.tgtcode,l.bizdate FROM nested_pair l INNER JOIN branch_3 r ON r.mktcode=l.mktcode AND r.tgtcode=l.tgtcode AND r.bizdate=l.bizdate;
